// Environment Variable Validation Module
// Ensures all required environment variables are present

const requiredEnvVars = [
  'PORT',
  'NODE_ENV',
];

const optionalEnvVars = [
  'DATABASE_URL',
  'JWT_SECRET',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'ALLOWED_ORIGINS',
];

/**
 * Validates that all required environment variables are set
 * Exits the process if any are missing
 */
function validateEnv() {
  const missing = requiredEnvVars.filter(
    (key) => !process.env[key]
  );

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables:');
    missing.forEach((key) => {
      console.error(`   - ${key}`);
    });
    console.error('\nPlease check your .env file and ensure all required variables are set.');
    process.exit(1);
  }

  // Warn about optional variables
  const missingOptional = optionalEnvVars.filter(
    (key) => !process.env[key]
  );

  if (missingOptional.length > 0) {
    console.warn('⚠️  Optional environment variables not set:');
    missingOptional.forEach((key) => {
      console.warn(`   - ${key}`);
    });
  }

  console.log('✅ Environment validation passed');
}

/**
 * Gets an environment variable with type checking
 * @param {string} key - The environment variable name
 * @param {string} defaultValue - Default value if not set
 * @returns {string} The environment variable value
 */
function getEnv(key, defaultValue = undefined) {
  const value = process.env[key];

  if (value === undefined && defaultValue === undefined) {
    throw new Error(`Environment variable ${key} is not set`);
  }

  return value || defaultValue;
}

/**
 * Gets an environment variable as a number
 * @param {string} key - The environment variable name
 * @param {number} defaultValue - Default value if not set
 * @returns {number} The environment variable as a number
 */
function getEnvNumber(key, defaultValue = undefined) {
  const value = process.env[key];

  if (value === undefined) {
    if (defaultValue === undefined) {
      throw new Error(`Environment variable ${key} is not set`);
    }
    return defaultValue;
  }

  const num = parseInt(value, 10);

  if (isNaN(num)) {
    throw new Error(`Environment variable ${key} is not a valid number: ${value}`);
  }

  return num;
}

/**
 * Gets an environment variable as a boolean
 * @param {string} key - The environment variable name
 * @param {boolean} defaultValue - Default value if not set
 * @returns {boolean} The environment variable as a boolean
 */
function getEnvBool(key, defaultValue = undefined) {
  const value = process.env[key];

  if (value === undefined) {
    if (defaultValue === undefined) {
      throw new Error(`Environment variable ${key} is not set`);
    }
    return defaultValue;
  }

  return value.toLowerCase() === 'true' || value === '1';
}

module.exports = {
  validateEnv,
  getEnv,
  getEnvNumber,
  getEnvBool,
  requiredEnvVars,
  optionalEnvVars,
};

